html:
{#- A custom format places the letter head itself: #header-html / #footer-html are
    what the PDF repeats on every page (the footer shows in the PDF only). -#}
<div id="header-html" class="hidden-pdf">
	{%- if letter_head and not no_letterhead %}<div class="letter-head">{{ letter_head }}</div>{% endif %}
</div>
<div id="footer-html" class="visible-pdf">
	{%- if not no_letterhead and footer %}<div class="letter-head-footer">{{ footer }}</div>{% endif %}
</div>
<style>
	.dn { font-family: Arial, Helvetica, sans-serif; font-size: 11.5px; color: #1f2a44; }
	.dn-title { width: 100%; border-collapse: collapse; border-bottom: 1px solid #e2e5ea; margin: 4px 0 14px; }
	.dn-title td { padding: 10px 0; vertical-align: middle; border: 0; }
	.dn-title h1 { font-size: 19px; margin: 0; color: #1f2a44; }
	.dn-title .sub { color: #8a94a6; font-size: 11px; margin-top: 3px; }
	.dn h2 { font-size: 12px; text-transform: uppercase; letter-spacing: .05em; color: #003277; border-left: 4px solid #ec2e5d; padding-left: 8px; margin: 18px 0 8px; }
	.dn-top { width: 100%; border-collapse: collapse; }
	.dn-top > tbody > tr > td { vertical-align: top; border: 0; padding: 0; }
	.dn-to { line-height: 1.55; font-size: 11.5px; }
	.dn-to .name { font-size: 13px; font-weight: bold; }
	.dn-to .ar { direction: rtl; font-size: 12px; }
	.dn-ref { width: 100%; border-collapse: collapse; }
	.dn-ref td { padding: 2px 0 !important; border: 0; font-size: 11.5px; line-height: 1.5; vertical-align: top; }
	.dn-ref td.k { width: 120px; color: #5a6478; font-weight: bold; }
	.dn-kv { width: 100%; border-collapse: collapse; }
	.dn-kv td { width: 25%; padding: 4px 10px 8px 0; vertical-align: top; border: 0; }
	.dn-kv .k { font-size: 9.5px; text-transform: uppercase; letter-spacing: .04em; color: #8a94a6; font-weight: bold; }
	.dn-kv .v { font-size: 12px; font-weight: bold; margin-top: 2px; }
	.dn-t { width: 100%; border-collapse: collapse; }
	.dn-t th { background: #f4f5f7; text-align: left; padding: 7px 8px; border: 1px solid #e2e5ea; font-size: 10px; text-transform: uppercase; letter-spacing: .03em; color: #5a6478; }
	/* Desk's print styles enlarge table text; pin it to the report's size. */
	.dn-t td, .dn-t td b { padding: 7px 8px; border: 1px solid #e2e5ea; vertical-align: top; font-size: 11.5px; line-height: 1.45; }
	.dn-t td b { padding: 0; border: 0; }
	.dn-t .num { text-align: right; white-space: nowrap; }
	.dn-t .muted { color: #8a94a6; font-size: 10.5px; }
	.dn-t tr { page-break-inside: avoid; }
	.dn-t tfoot td { font-weight: bold; background: #fafbfc; }
	.pill { display: inline-block; border-radius: 10px; padding: 2px 9px; font-size: 10px; font-weight: bold; background: #eef0f4; }
	.pill-ok { background: #e7f8ee; color: #15803d; }
	.pill-bad { background: #fde7ee; color: #c01643; }
	.dn-note { border: 1px solid #e2e5ea; background: #fafbfc; padding: 9px 11px; margin-top: 14px; font-size: 11px; line-height: 1.5; page-break-inside: avoid; }
	.dn-sigs { width: 100%; border-collapse: collapse; margin-top: 40px; page-break-inside: avoid; }
	.dn-sigs td { border: 0; }
	.dn-sigs .box { border: 1px solid #e2e5ea; padding: 10px 12px 14px; }
	.dn-sigs .box h4 { font-size: 10.5px; text-transform: uppercase; letter-spacing: .05em; color: #003277; margin: 0 0 10px; }
	.dn-sigs .dn-line { font-size: 11px; color: #5a6478; padding: 9px 0 2px; border-bottom: 1px dotted #c9ced8; margin: 0; }
	/* Desk's print styles pad every table cell; the layout tables here sit flush
	   so every section starts on the same left edge as the items table. */
	.dn .dn-title td { padding: 10px 0 !important; }
	.dn .dn-top > tbody > tr > td { padding: 0 !important; }
	.dn .dn-top td.left { width: 55%; padding-right: 20px !important; }
	.dn .dn-top td.right { width: 45%; }
	.dn .dn-kv td { padding: 4px 10px 8px 0 !important; }
	.dn .dn-ref td { padding: 2px 0 !important; }
	.dn .dn-sigs td { padding: 0 !important; vertical-align: top; }
	.dn .dn-sigs td.side { width: 48%; }
	.dn .dn-sigs td.gap { width: 4%; }
	.dn-sigs .box h4 { margin: 0 0 2px; }
	.dn-sigs .who { font-size: 11.5px; font-weight: bold; color: #1f2a44; margin-bottom: 4px; }
</style>
{%- set addr_name = doc.shipping_address_name or doc.customer_address -%}
{%- set addr = frappe.get_doc("Address", addr_name) if addr_name else None -%}
{%- set trn = frappe.db.get_value("Customer", doc.customer, "tax_id") -%}
{%- set phone = doc.contact_mobile or doc.contact_phone or (addr.phone if addr else "") -%}
{%- set orders = doc.items | map(attribute="against_sales_order") | select | unique | list -%}
{%- set chassis = doc.get("custom_chassis_number") -%}
{%- set serial = doc.get("custom_trailer_serial") -%}
{%- set customer_chassis = doc.get("custom_customer_chassis_number") -%}
{%- set ns = namespace(qty=0) -%}
{#- The note-level chassis numbers belong to one line: the item ticked "Is a Trailer"
    (when exactly one is), else the first line (e.g. trailer + spare wheel). -#}
{%- set trailer_codes = frappe.get_all("Item", filters={"name": ["in", doc.items | map(attribute="item_code") | list], "custom_is_trailer": 1}, pluck="name") -%}
{%- set trailer_rows = doc.items | selectattr("item_code", "in", trailer_codes) | list -%}
{%- set chassis_row = trailer_rows[0].name if trailer_rows | length == 1 else (doc.items[0].name if not trailer_rows and doc.items else None) -%}
<div class="dn">
	<table class="dn-title"><tr>
		<td>
			<h1>Delivery Note</h1>
			<div class="sub">{{ doc.name }} &middot; {{ doc.customer_name }}</div>
		</td>
	</tr></table>

	<table class="dn-top"><tr>
		<td class="left">
			<h2 style="margin-top:0">Deliver To</h2>
			<div class="dn-to">
				<div class="name">{{ doc.customer_name }}</div>
				{%- if doc.get("customer_name_in_arabic") %}<div class="ar">{{ doc.customer_name_in_arabic }}</div>{% endif %}
				{%- if addr %}
				<div>{{ addr.address_line1 or "" }}{% if addr.address_line2 %}, {{ addr.address_line2 }}{% endif %}</div>
				<div>{{ addr.city or "" }}{% if addr.state %}, {{ addr.state }}{% endif %}{% if addr.country %}, {{ addr.country }}{% endif %}</div>
				{%- endif %}
				{%- if doc.contact_display %}<div>Attn: {{ doc.contact_display }}</div>{% endif %}
				{%- if phone %}<div>Tel: {{ phone }}</div>{% endif %}
				{%- if trn %}<div>TRN: {{ trn }}</div>{% endif %}
			</div>
		</td>
		<td class="right">
			<h2 style="margin-top:0">Reference</h2>
			<table class="dn-ref">
				<tr><td class="k">Delivery Note No</td><td><b>{{ doc.name }}</b></td></tr>
				<tr><td class="k">Date</td><td>{{ frappe.utils.formatdate(doc.posting_date, "dd-MM-yyyy") }}</td></tr>
				{%- if orders %}<tr><td class="k">Sales Order</td><td>{{ orders | join(", ") }}</td></tr>{% endif %}
				{%- if doc.po_no %}<tr><td class="k">Customer PO</td><td>{{ doc.po_no }}{% if doc.po_date %} ({{ frappe.utils.formatdate(doc.po_date, "dd-MM-yyyy") }}){% endif %}</td></tr>{% endif %}
				{%- if doc.get("permit_no") %}<tr><td class="k">Permit No</td><td>{{ doc.permit_no }}</td></tr>{% endif %}
			</table>
		</td>
	</tr></table>

	{%- if chassis or customer_chassis or serial or doc.vehicle_no or doc.driver_name or doc.transporter_name or doc.lr_no %}
	<h2>Trailer &amp; Chassis Number</h2>
	<table class="dn-kv"><tr>
		{%- if chassis %}<td><div class="k">Chassis Number</div><div class="v">{{ chassis }}</div></td>{% endif %}
		{%- if customer_chassis %}<td><div class="k">Customer Chassis Number</div><div class="v">{{ customer_chassis }}</div></td>{% endif %}
		{%- if serial %}<td><div class="k">Trailer Serial</div><div class="v">{{ serial }}</div></td>{% endif %}
		{%- if doc.vehicle_no %}<td><div class="k">Vehicle No</div><div class="v">{{ doc.vehicle_no }}</div></td>{% endif %}
		{%- if doc.driver_name %}<td><div class="k">Driver</div><div class="v">{{ doc.driver_name }}</div></td>{% endif %}
		{%- if doc.transporter_name %}<td><div class="k">Transporter</div><div class="v">{{ doc.transporter_name }}</div></td>{% endif %}
		{%- if doc.lr_no %}<td><div class="k">Transport Receipt No</div><div class="v">{{ doc.lr_no }}</div></td>{% endif %}
	</tr></table>
	{%- endif %}

	<h2>Items Delivered</h2>
	<table class="dn-t">
		<thead><tr><th style="width:28px">#</th><th>Item</th><th>Serial / Chassis No</th><th>Customer Chassis No</th><th class="num" style="width:50px">Qty</th><th style="width:50px">Unit</th><th style="width:110px">QC</th></tr></thead>
		<tbody>
		{%- for it in doc.items %}
			{%- set ns.qty = ns.qty + (it.qty or 0) -%}
			{%- set qi_status = frappe.db.get_value("Quality Inspection", it.quality_inspection, "status") if it.quality_inspection else None -%}
			<tr>
				<td>{{ loop.index }}</td>
				<td><b>{{ it.item_name }}</b><div class="muted">{{ it.item_code }}{% if it.description and it.description | striptags | trim != it.item_name %} &middot; {{ it.description | striptags | truncate(120) }}{% endif %}</div></td>
				<td>{{ (it.serial_no or "") | replace("\n", ", ") or (chassis if it.name == chassis_row else "") or "—" }}</td>
				<td>{{ (customer_chassis if it.name == chassis_row else "") or "—" }}</td>
				<td class="num">{{ "%g" | format(it.qty or 0) }}</td>
				<td>{{ it.uom or it.stock_uom }}</td>
				<td>{% if qi_status %}<span class="pill {{ 'pill-ok' if qi_status == 'Accepted' else 'pill-bad' }}">{{ qi_status }}</span><div class="muted">{{ it.quality_inspection }}</div>{% else %}—{% endif %}</td>
			</tr>
		{%- endfor %}
		</tbody>
		<tfoot><tr><td colspan="4" class="num">Total quantity</td><td class="num">{{ "%g" | format(ns.qty) }}</td><td colspan="2"></td></tr></tfoot>
	</table>

	{%- set note = doc.get("instructions") or doc.get("terms") %}
	{%- if note %}
	<h2>Instructions</h2>
	<div style="white-space:pre-wrap">{{ note | striptags }}</div>
	{%- endif %}


	<div class="dn-note">Received the above goods in good order and condition. Please check the goods, the chassis number and the quantity before signing; claims after signing are not accepted.</div>

	<table class="dn-sigs"><tr>
		<td class="side">
			<div class="box">
				<h4>Delivered By</h4>
				<div class="who">Redlines International Trading LLC</div>
				<div class="dn-line">Name:</div>
				<div class="dn-line">Signature:</div>
				<div class="dn-line">Date:</div>
				<div style="text-align:right;margin-top:-62px;height:62px">{{ rli_stamp(84, "opacity:.92") }}</div>
			</div>
		</td>
		<td class="gap"></td>
		<td class="side">
			<div class="box">
				<h4>Received By</h4>
				<div class="who">{{ doc.customer_name }}</div>
				<div class="dn-line">Name:</div>
				<div class="dn-line">Signature &amp; Stamp:</div>
				<div class="dn-line">Date:</div>
			</div>
		</td>
	</tr></table>
</div>
